#!/usr/bin/env bash
# Unattended durability layer for the Rybbit log sink.
# Daily: Postgres logical dump + stack config/secrets. Weekly: ClickHouse data snapshot.
# Bounded rotation (7 daily / 4 weekly) so disk never fills unattended.
# Installed to /opt/rybbit-deploy/backup.sh and run by root cron at 03:15 daily.
set -euo pipefail

BACKUP_ROOT=/opt/rybbit-backups
STAMP=$(date +%Y%m%d-%H%M%S)
DOW=$(date +%u)
mkdir -p "$BACKUP_ROOT/daily" "$BACKUP_ROOT/weekly"
cd /opt/rybbit

# Load stack credentials generated by setup.sh.
set -a; [ -f .env ] && . ./.env; set +a

# Postgres logical dump (consistent, restoreable).
docker exec postgres pg_dump -U "${POSTGRES_USER:-frog}" "${POSTGRES_DB:-analytics}" \
  > "$BACKUP_ROOT/daily/postgres-$STAMP.sql" 2>/dev/null || true

# Config + secrets needed to rebuild the stack (.env, Caddyfile, compose files).
tar czf "$BACKUP_ROOT/daily/config-$STAMP.tar.gz" \
  .env Caddyfile docker-compose.yml docker-compose.watchtower.yml 2>/dev/null || true

# Weekly ClickHouse data snapshot (the analytics/log store itself).
if [ "$DOW" = "7" ]; then
  CH_VOL=$(docker volume ls --format '{{.Name}}' | grep 'clickhouse-data' | head -1 || true)
  if [ -n "$CH_VOL" ]; then
    docker run --rm -v "$CH_VOL:/data:ro" -v "$BACKUP_ROOT/weekly:/backup" alpine \
      tar czf "/backup/clickhouse-$STAMP.tar.gz" -C /data . 2>/dev/null || true
  fi
fi

# Rotation: keep 7 daily, 4 weekly.
ls -1t "$BACKUP_ROOT/daily/"postgres-*.sql 2>/dev/null | tail -n +8 | xargs -r rm -f
ls -1t "$BACKUP_ROOT/daily/"config-*.tar.gz 2>/dev/null | tail -n +8 | xargs -r rm -f
ls -1t "$BACKUP_ROOT/weekly/"clickhouse-*.tar.gz 2>/dev/null | tail -n +5 | xargs -r rm -f
